<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useAuthStore } from '@/stores/auth-store'
import { useMenuCategoriesStore } from '@/stores/menu-categories-store'
import { useMenuItemsStore } from '@/stores/menu-items-store'
import { useMenusStore } from '@/stores/menus-store'
import { useRestaurantUsersStore } from '@/stores/restaurant-users-store'
import type { MenuItem } from '@/types/menu'

const route = useRoute(); const authStore = useAuthStore(); const itemsStore = useMenuItemsStore(); const categoriesStore = useMenuCategoriesStore(); const menusStore = useMenusStore(); const restaurantUsersStore = useRestaurantUsersStore(); const editingItem = ref<string | null>(null)
const isManager = computed(() => route.path.startsWith('/manager'))
const managedRestaurantIds = computed(() => authStore.isRoot || !isManager.value || !authStore.userId ? null : new Set(restaurantUsersStore.adminRestaurantIds(authStore.userId)))
const availableMenus = computed(() => managedRestaurantIds.value ? menusStore.menus.filter((menu) => managedRestaurantIds.value?.has(menu.restaurantId)) : menusStore.menus)
const availableMenuIds = computed(() => new Set(availableMenus.value.map((menu) => menu.id)))
const availableCategories = computed(() => categoriesStore.categories.filter((category) => availableMenuIds.value.has(category.menuId)))
const availableCategoryIds = computed(() => new Set(availableCategories.value.map((category) => category.id)))
const visibleItems = computed(() => itemsStore.items.filter((item) => availableCategoryIds.value.has(item.menuCategoryId)))
const itemForm = reactive({ menuCategoryId: '', name: '', description: '', price: 0, isAvailable: true, imageUrl: '', summary: '' })
const editItemForm = reactive({ menuCategoryId: '', name: '', description: '', price: 0, isAvailable: true, imageUrl: '', summary: '' })
const hasError = computed(() => itemsStore.error || categoriesStore.error || menusStore.error || restaurantUsersStore.error)
async function submitItem(): Promise<void> { const created = await itemsStore.createItemWithValidation(itemForm); if (created) { itemForm.name = ''; itemForm.description = ''; itemForm.price = 0; itemForm.imageUrl = ''; itemForm.summary = '' } }
function startEditItem(item: MenuItem): void { editingItem.value = item.id; editItemForm.menuCategoryId = item.menuCategoryId ?? ''; editItemForm.name = item.name ?? ''; editItemForm.description = item.description ?? ''; editItemForm.price = item.price; editItemForm.isAvailable = item.isAvailable; editItemForm.imageUrl = item.imageUrl ?? ''; editItemForm.summary = item.summary ?? '' }
function cancelEditItem(): void { editingItem.value = null; itemsStore.clearError() }
async function submitEditItem(item: MenuItem): Promise<void> { const updated = await itemsStore.updateItemWithValidation({ id: item.id, ...editItemForm }); if (updated) editingItem.value = null }
onMounted(() => { void Promise.all([itemsStore.loadItems(), categoriesStore.loadCategories(), menusStore.loadMenus(), restaurantUsersStore.loadRestaurantUsers()]) })
</script>

<template><main class="items-page"><h1>{{ isManager ? 'Manager menu items' : 'Admin menu items' }}</h1><p v-if="hasError" class="error">{{ hasError }}</p><section class="panel"><form class="grid" @submit.prevent="submitItem"><label>Category<select v-model="itemForm.menuCategoryId"><option value="" disabled>Select category</option><option v-for="item in availableCategories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Name<input v-model.trim="itemForm.name" type="text" /></label><label>Description<input v-model.trim="itemForm.description" type="text" /></label><label>Price<input v-model.number="itemForm.price" type="number" min="0" step="0.01" /></label><label>Image URL<input v-model.trim="itemForm.imageUrl" type="text" /></label><label>Summary<input v-model.trim="itemForm.summary" type="text" /></label><label class="inline-checkbox"><input v-model="itemForm.isAvailable" type="checkbox" />Available</label><button type="submit">Add</button></form></section><section class="panel"><ul><li v-for="item in visibleItems" :key="item.id" class="item-card"><form v-if="editingItem === item.id" class="inline-form" @submit.prevent="submitEditItem(item)"><select v-model="editItemForm.menuCategoryId"><option v-for="category in availableCategories" :key="category.id" :value="category.id">{{ category.name }}</option></select><input v-model.trim="editItemForm.name" type="text" /><input v-model.trim="editItemForm.description" type="text" /><input v-model.number="editItemForm.price" type="number" min="0" step="0.01" /><input v-model.trim="editItemForm.imageUrl" type="text" /><input v-model.trim="editItemForm.summary" type="text" /><label class="inline-checkbox"><input v-model="editItemForm.isAvailable" type="checkbox" />Available</label><button type="submit">Save</button><button type="button" @click="cancelEditItem">Cancel</button></form><template v-else><div><strong>{{ item.name }}</strong><p class="summary-muted">{{ item.description || 'No description' }}</p><p class="sort-muted">{{ categoriesStore.categoryNameById(item.menuCategoryId) }}</p><span class="price-tag">${{ item.price.toFixed(2) }}</span><span :class="item.isAvailable ? 'available' : 'unavailable'">{{ item.isAvailable ? 'Available' : 'Unavailable' }}</span></div><div class="actions"><button type="button" @click="startEditItem(item)">Edit</button><button type="button" @click="itemsStore.removeItem(item.id)">Delete</button></div></template></li></ul></section></main></template>

<style scoped>
.items-page{max-width:850px;margin:0 auto;padding:1.5rem}.panel{border:1px solid #d5d9e2;border-radius:12px;padding:1rem;background:#fff;margin-bottom:1.2rem}.grid{display:grid;gap:.8rem;grid-template-columns:repeat(auto-fit,minmax(220px,1fr))}.inline-form{display:flex;flex-wrap:wrap;gap:.5rem;margin-bottom:.6rem}label{display:grid;gap:.35rem}input,select{border:1px solid #b8c0cc;border-radius:8px;padding:.5rem .6rem;font:inherit}button{border:1px solid #0f4c81;border-radius:8px;background:#0f4c81;color:#fff;padding:.45rem .7rem;cursor:pointer;font:inherit}ul{list-style:none;margin:0;padding:0;display:grid;gap:.45rem}.item-card{display:flex;align-items:center;justify-content:space-between;gap:.7rem;border:1px solid #e5e7eb;border-radius:8px;padding:.6rem}.actions{display:flex;gap:.45rem;flex-wrap:wrap}.sort-muted{color:#6b7280;font-size:.92em;margin:.2rem 0}.summary-muted{margin:.2rem 0;color:#4b5563}.inline-checkbox{display:inline-flex;align-items:center;gap:.4rem}.price-tag{display:inline-block;margin-right:.5rem;color:#0f4c81;font-weight:700}.available,.unavailable{display:inline-block;border-radius:999px;padding:.12rem .5rem;font-size:.82rem}.available{background:#dcfce7;color:#166534}.unavailable{background:#e5e7eb;color:#374151}.error{margin:0;color:#a61b1b}
</style>
